package school.magiccodex.client;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NotificationPresentationTest {
 NotificationQueue.Notice notice(String id){return new NotificationQueue.Notice(id,"quest","한글 제목","본문",1000);}
 @Test void worldCursorAndDialogueHaveExactlyOneOwner(){var p=new NotificationPresentation();for(var s:NotificationPresentation.Surface.values()){var frame=new Object();boolean hud=p.owns(frame,false,s),screen=p.owns(frame,true,s);assertEquals(s!=NotificationPresentation.Surface.HIDDEN,hud||screen);assertFalse(hud&&screen);assertFalse(p.owns(frame,true,s));}}
 @Test void duplicateScreenCallbacksCannotRedrawOrClearTheCurrentFrame(){var p=new NotificationPresentation();Object frame=new Object();assertTrue(p.owns(frame,true,NotificationPresentation.Surface.DIALOGUE));assertFalse(p.owns(frame,true,NotificationPresentation.Surface.DIALOGUE));assertTrue(p.owns(new Object(),true,NotificationPresentation.Surface.DIALOGUE));}
 @Test void hiddenReceiptAnnouncesOnlyAtFirstVisibleFrame(){var q=new NotificationQueue();q.offer(notice("a"));q.frame(0,false,3);q.frame(5000,false,3);var first=q.frame(5050,true,3).getFirst();assertEquals(0,first.age());assertTrue(first.announce());assertFalse(q.frame(5050,true,3).getFirst().announce());assertFalse(q.offerIfAbsent(notice("a")));assertFalse(q.frame(5100,true,3).getFirst().announce());}
 @Test void screenTransitionPausesWithoutRestartingFadeOrReplayingSound(){var q=new NotificationQueue();q.offer(notice("a"));q.frame(0,true,3);q.frame(100,true,3);q.frame(200,false,3);var v=q.frame(20000,true,3).getFirst();assertEquals(100,v.age());assertFalse(v.announce());assertEquals(NotificationPresentation.alpha(100,1000),NotificationPresentation.alpha(v.age(),1000));}
 @Test void sameTimestampAndBackwardsClockDoNotAdvanceAgeTwice(){var q=new NotificationQueue();q.offer(notice("a"));q.frame(100,true,3);assertEquals(100,q.frame(200,true,3).getFirst().age());assertEquals(100,q.frame(200,true,3).getFirst().age());assertEquals(100,q.frame(150,true,3).getFirst().age());assertEquals(150,q.frame(250,true,3).getFirst().age());}
 @Test void threeNoticesHaveDistinctPositionsBeforeAnyTimePasses(){var q=new NotificationQueue();q.offer(notice("a"));q.offer(notice("b"));q.offer(notice("c"));var v=q.frame(0,true,3);assertEquals(java.util.List.of(0d,1d,2d),v.stream().map(NotificationQueue.Visible::slot).toList());assertTrue(v.stream().allMatch(NotificationQueue.Visible::announce));}
 @Test void hiddenOverflowDoesNotConsumeItsFirstDisplayCue(){var q=new NotificationQueue();q.offer(notice("a"));q.offer(notice("b"));assertEquals("b",q.frame(0,true,1).getFirst().notice().id());q.dismiss("b");assertTrue(q.frame(10,true,1).getFirst().announce());}
 @Test void alphaIsBoundedAndOnlyFadesAtEdges(){assertEquals(0,NotificationPresentation.alpha(-1,1000));assertEquals(0,NotificationPresentation.alpha(1001,1000));assertEquals(1,NotificationPresentation.alpha(300,1000));assertEquals(1,NotificationPresentation.alpha(600,1000));assertEquals(.5f,NotificationPresentation.alpha(800,1000));}
}
